def charge(gateway, order):
    try:
        return gateway.charge(order)
    except TimeoutError:
        return gateway.charge(order)

def charge(gateway, order, key):
    try:
        return gateway.charge(order, idempotency_key=key)
    except TimeoutError:
        return gateway.charge(order, idempotency_key=key)

